-- 072_seed_bdb_crime_master.sql
-- Seed bdb_crime_master (referensi "Crime Master" -- kategori/jenis_kejahatan/nama_kejahatan_canonical
-- per dors_crime_id, dipakai fitur GET/PATCH /bdb/master/kejahatan dan FK bdb_lp_master.crime_master_id).
-- Data ini SEBELUMNYA cuma bisa diisi lewat script manual (scripts/bdb/import-qcb-crimes.js, baca CSV
-- dari mesin developer -- tidak ada di repo) atau scripts/bdb/import-dors-response.js (import manual
-- dari dump respons DORS) -- belum pernah ada migration utk data ini. Disiapkan sekarang sbg jaga-jaga
-- sebelum fitur ini benar-benar dipakai lewat UI (blm ada frontend page yg memanggilnya per 2026-08-02).
-- Idempotent (ON CONFLICT DO NOTHING), aman dijalankan ulang.

on conflict (id) do nothing;
select setval(pg_get_serial_sequence('bdb_crime_master', 'id'), greatest((select coalesce(max(id),0) from bdb_crime_master), 1));
